#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int earliestFinishTime(std::vector<int>& landStartTime, std::vector<int>& landDuration, std::vector<int>& waterStartTime, std::vector<int>& waterDuration) {
        int best = INT_MAX;
        int n_l = landStartTime.size();
        int n_w = waterStartTime.size();

        for (int i = 0; i < n_l; ++i) {
            int l_finish = landStartTime[i] + landDuration[i];
            for (int j = 0; j < n_w; ++j) {
                int w_finish = waterStartTime[j] + waterDuration[j];

                int finish_lw = std::max(l_finish, waterStartTime[j]) + waterDuration[j];
                int finish_wl = std::max(w_finish, landStartTime[i]) + landDuration[i];
                best = std::min({best, finish_lw, finish_wl});
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public int earliestFinishTime(int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
        int best = Integer.MAX_VALUE;
        int nL = landStartTime.length;
        int nW = waterStartTime.length;

        for (int i = 0; i < nL; i++) {
            int lFinish = landStartTime[i] + landDuration[i];
            for (int j = 0; j < nW; j++) {
                int wFinish = waterStartTime[j] + waterDuration[j];

                int finishLW = Math.max(lFinish, waterStartTime[j]) + waterDuration[j];
                int finishWL = Math.max(wFinish, landStartTime[i]) + landDuration[i];
                best = Math.min(best, Math.min(finishLW, finishWL));
            }
        }
        return best;
    }
}

